unsigned long long simple_strtoull(const char *cp, char **endp, unsigned int base) /* <=== simple_strtoull */ 
{
	unsigned long long result;
	unsigned int rv;

	cp = _parse_integer_fixup_radix(cp, &base);
	rv = _parse_integer(cp, base, &result);
	/* FIXME */
	cp += (rv & ~KSTRTOX_OVERFLOW);

	if (endp)
		*endp = (char *)cp;

	return result;
}

static __inline__ void /* <=== clear_bit */ 
clear_bit (int nr, volatile void *addr)
{
	__u32 mask, old, new;
	volatile __u32 *m;
	CMPXCHG_BUGCHECK_DECL

	m = (volatile __u32 *) addr + (nr >> 5);
	mask = ~(1 << (nr & 31));
	do {
		CMPXCHG_BUGCHECK(m);
		old = *m;
		new = old & mask;
	} while (cmpxchg_acq(m, old, new) != old);
}

long simple_strtol(const char *cp, char **endp, unsigned int base) /* <=== simple_strtol */ 
{
	if (*cp == '-')
		return -simple_strtoul(cp + 1, endp, base);

	return simple_strtoul(cp, endp, base);
}

static struct o2net_node * o2net_nn_from_num(u8 node_num) /* <=== o2net_nn_from_num */ 
{
	BUG_ON(node_num >= ARRAY_SIZE(o2net_nodes));
	return &o2net_nodes[node_num];
}

static inline void set_bit(int nr, volatile unsigned long *addr) /* <=== set_bit */ 
{
	unsigned long mask = BIT_MASK(nr);
	unsigned long *p = ((unsigned long *)addr) + BIT_WORD(nr);
	unsigned long flags;

	_atomic_spin_lock_irqsave(p, flags);
	*p  |= mask;
	_atomic_spin_unlock_irqrestore(p, flags);
}

static inline void clear_bit(unsigned nr, volatile unsigned long *addr) /* <=== clear_bit */ 
{
	_atomic_fetch_andn(addr + BIT_WORD(nr), BIT_MASK(nr));
}

static inline int test_and_set_bit(unsigned nr, volatile unsigned long *addr) /* <=== test_and_set_bit */ 
{
	int val;
	unsigned long mask = (1UL << (nr % BITS_PER_LONG));
	smp_mb();  /* barrier for proper semantics */
	val = (__insn_fetchor((void *)(addr + nr / BITS_PER_LONG), mask)
	       & mask) != 0;
	barrier();
	return val;
}

